template.script:
(function () {
    var match = /[?&]sitepage=(\d+)/.exec(document.location.search);
    if (match && match[1] === '1') {
        document.querySelectorAll('.acc_footer_first').forEach(function (el) { el.style.display = 'inline'; });
        document.querySelectorAll('.acc_footer_other').forEach(function (el) { el.style.display = 'none'; });
    }
})();
